import math

def triangle_area(a, b, c):
    def is_valid_triangle(a, b, c):
        if a <= 0 or b <= 0 or c <= 0:
            return False
        if a + b > c and a + c > b and b + c > a:
            return True
        return False

    if not is_valid_triangle(a, b, c):
        return -1

    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))
    rounded_area = round(area, 2)

    return rounded_area

