def fizz_buzz(n: int):
    """
    Count digit 7 in numbers under n divisible by 11 or 13.

    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
    3
    """
    def has_seven(num):
        return '7' in str(num)

    count = 0
    for i in range(1, n):
        if has_seven(i) and (i % 11 == 0 or i % 13 == 0):
            count += 1

    return count

