from typing import List

def sort_numbers(numbers: str) -> str:
    words_to_num = {
        'zero': 0,
        'one': 1,
        'two': 2,
        'three': 3,
        'four': 4,
        'five': 5,
        'six': 6,
        'seven': 7,
        'eight': 8,
        'nine': 9
    }

    def word_to_num(word):
        return words_to_num[word]

    def num_to_word(num):
        return [key for key, value in words_to_num.items() if value == num][0]

    if not numbers:
        return ''

    words = numbers.split()
    nums = [word_to_num(word) for word in words]
    sorted_nums = sorted(nums)
    sorted_words = [num_to_word(num) for num in sorted_nums]

    return ' '.join(sorted_words)
